static int mc(jas_iccattrval_t *zb, jas_stream_t *xo,
  int rd)
{
	jas_icccurv_t *curv = &zb->data.curv;
	unsigned int i;

	curv->numents = 0;
	curv->ents = 0;

	if (jas_iccgetuint32(xo, &curv->numents))
		goto error;
	if (!(curv->ents = jas_malloc(curv->numents * sizeof(jas_iccuint16_t))))
		goto error;
	for (i = 0; i < curv->numents; ++i) {
		if (jas_iccgetuint16(xo, &curv->ents[i]))
			goto error;
	}

	if (JAS_CAST(int, 4 + 2 * curv->numents) != rd)
		goto error;
	return 0;

error:
	jas_icccurv_destroy(zb);
	return -1;
}

