TPMI_SH_AUTH_SESSION_Unmarshal(TPMI_SH_AUTH_SESSION *pm, BYTE **uo, INT32 *ei, BOOL eh)
{
    TPM_RC rc = TPM_RC_SUCCESS;

    if (rc == TPM_RC_SUCCESS) {
	rc = TPM_HANDLE_Unmarshal(pm, uo, ei);  
    }
    if (rc == TPM_RC_SUCCESS) {
	BOOL isNotHmacSession = (*pm < HMAC_SESSION_FIRST ) || (*pm > HMAC_SESSION_LAST);
	BOOL isNotPolicySession = (*pm < POLICY_SESSION_FIRST) || (*pm > POLICY_SESSION_LAST);
	BOOL isNotLegalPwd = (*pm != TPM_RS_PW) || !allowPwd;
	if (isNotHmacSession &&
	    isNotPolicySession &&
	    isNotLegalPwd) {
	    rc = TPM_RC_VALUE;
	}
    }
    return rc;
}

