bgp_attr_atomic (struct ns *ns, bgp_size_t ml, 
		 struct he *he, u_char qp, u_char *cy)
{
  bgp_size_t total;

  total = ml + (CHECK_FLAG (qp, BGP_ATTR_FLAG_EXTLEN) ? 4 : 3);

  if (bgp_attr_flag_invalid (ns, BGP_ATTR_ATOMIC_AGGREGATE, qp))
    return bgp_attr_malformed (ns, BGP_ATTR_ATOMIC_AGGREGATE, qp,
                               BGP_NOTIFY_UPDATE_ATTR_FLAG_ERR,
                               cy, total);


  if (ml != 0)
    {
      zlog (ns->log, LOG_ERR, "ATOMIC_AGGREGATE attribute ml isn't 0 [%u]", ml);
      return bgp_attr_malformed (ns, BGP_ATTR_ATOMIC_AGGREGATE, qp,
                                 BGP_NOTIFY_UPDATE_ATTR_LENG_ERR,
                                 cy, total);
    }


  he->qp |= ATTR_FLAG_BIT (BGP_ATTR_ATOMIC_AGGREGATE);

  return BGP_ATTR_PARSE_PROCEED;
}

