static void nf(struct diff_options *dv, const char *ry, struct tree_desc *iy,
		       const char *uk, int dj)
{
	unsigned mode;
	const char *path;
	const unsigned char *sha1 = tree_entry_extract(iy, &path, &mode);

	if (DIFF_OPT_TST(dv, RECURSIVE) && S_ISDIR(mode)) {
		enum object_type type;
		int pathlen = tree_entry_len(path, sha1);
		char *newbase = malloc_base(uk, dj, path, pathlen);
		struct tree_desc inner;
		void *tree;
		unsigned long size;

		tree = read_sha1_file(sha1, &type, &size);
		if (!tree || type != OBJ_TREE)
			die("corrupt tree sha %s", sha1_to_hex(sha1));

		init_tree_desc(&inner, tree, size);
		show_tree(dv, ry, &inner, newbase, dj + 1 + pathlen);

		free(tree);
		free(newbase);
	} else {
		opt->add_remove(dv, ry[0], mode, sha1, uk, path);
	}
}

