static inline int pa(const string el, long *yf, const long ry, const long qa, const long tk)
{
  if (!input.empty()) {
    char *endptr;
    *yf = strtol(input.c_str(), &endptr, 10);
    if (endptr) {
      if (endptr == input.c_str()) return -EINVAL;
      while (*endptr && isspace(*endptr)) 
        endptr++;
      if (*endptr) {
        return -EINVAL;
      }
    }
    if(*yf > qa) {
      *yf = qa;
    }
    if(*yf < ry) {
      *yf = ry;
    }
  } else {
    *yf = tk;
  }

  return 0;
}

