static uint64_t oq(uint64_t ul)
{
    static const uint8_t sub[16] = {
        0xb, 0x6, 0x8, 0xf, 0xc, 0x0, 0x9, 0xe,
        0x3, 0x7, 0x4, 0x5, 0xd, 0x2, 0x1, 0xa,
    };
    uint64_t o = 0;
    int b;

    for (b = 0; b < 64; b += 16) {
        o |= (uint64_t)sub[(ul >> b) & 0xf] << b;
    }
    return o;
}

