bool zo(struct asn1_data *fm, TALLOC_CTX *am, char **iz)
{
	DATA_BLOB blob;
	int len;

	if (!asn1_start_tag(fm, ASN1_OID)) return false;

	len = asn1_tag_remaining(fm);
	if (len < 0) {
		data->has_error = true;
		return false;
	}

	blob = data_blob(NULL, len);
	if (!blob.data) {
		data->has_error = true;
		return false;
	}

	asn1_read(fm, blob.data, len);
	asn1_end_tag(fm);
	if (fm->has_error) {
		data_blob_free(&blob);
		return false;
	}

	if (!ber_read_OID_String(am, blob, iz)) {
		data->has_error = true;
		data_blob_free(&blob);
		return false;
	}

	data_blob_free(&blob);
	return true;
}

