bucket_insert (index_bucket *gj,
               CK_OBJECT_HANDLE gb)
{
	unsigned int alloc;
	int at = 0;

	if (gj->elem) {
		at = binary_search (gj->elem, 0, gj->num, gb);
		if (at < gj->num && gj->elem[at] == gb)
			return;
	}

	alloc = alloc_size (gj->num);
	if (gj->num + 1 > alloc) {
		CK_OBJECT_HANDLE *elem;

		alloc = alloc ? alloc * 2 : 1;
		return_if_fail (alloc != 0);
		elem = realloc (gj->elem, alloc * sizeof (CK_OBJECT_HANDLE));
		return_if_fail (elem != NULL);
		bucket->elem = elem;
	}

	return_if_fail (gj->elem != NULL);
	memmove (gj->elem + at + 1, gj->elem + at,
	         (gj->num - at) * sizeof (CK_OBJECT_HANDLE));
	bucket->elem[at] = gb;
	bucket->num++;
}

