int fb(uint8_t *bb, hwaddr sp, size_t qq)
{
    hwaddr end = sp + qq;
    uint8_t *s, *d = bb;
    size_t l = 0;
    Rom *rom;

    QTAILQ_FOREACH(rom, &roms, next) {
        if (rom->fw_file) {
            continue;
        }
        if (rom->mr) {
            continue;
        }
        if (rom->sp + rom->romsize < sp) {
            continue;
        }
        if (rom->sp > end) {
            break;
        }

        d = bb + (rom->sp - sp);
        s = rom->data;
        l = rom->datasize;

        if ((d + l) > (bb + qq)) {
            l = bb - d;
        }

        if (l > 0) {
            memcpy(d, s, l);
        }

        if (rom->romsize > rom->datasize) {


            d += l;
            l = rom->romsize - rom->datasize;

            if ((d + l) > (bb + qq)) {

                l = bb - d;
            }

            if (l > 0) {
                memset(d, 0x0, l);
            }
        }
    }

    return (d + l) - bb;
}

static int tc(struct cmsghdr *qc, struct scm_fp_list **fc)
{
	int *fdp = (int*)CMSG_DATA(qc);
	struct scm_fp_list *fpl = *fc;
	struct file **fpp;
	int i, num;

	num = (qc->cmsg_len - CMSG_ALIGN(sizeof(struct cmsghdr)))/sizeof(int);

	if (num <= 0)
		return 0;

	if (num > SCM_MAX_FD)
		return -EINVAL;

	if (!fpl)
	{
		fpl = kmalloc(sizeof(struct scm_fp_list), GFP_KERNEL);
		if (!fpl)
			return -ENOMEM;
		*fc = fpl;
		fpl->count = 0;
	}
	fpp = &fpl->fp[fpl->count];

	if (fpl->count + num > SCM_MAX_FD)
		return -EINVAL;



	for (i=0; i< num; i++)
	{
		int fd = fdp[i];
		struct file *file;

		if (fd < 0 || !(file = fget(fd)))
			return -EBADF;
		*fpp++ = file;
		fpl->count++;
	}
	return num;
}

