check_sparse_region (struct tar_sparse_file *ki, off_t gv, off_t wk)
{
  if (!lseek_or_error (ki, gv))
    return false;

  while (gv < wk)
    {
      size_t bytes_read;
      size_t rdsize = BLOCKSIZE < wk - gv ? BLOCKSIZE : wk - gv;
      char diff_buffer[BLOCKSIZE];

      bytes_read = safe_read (ki->fd, diff_buffer, rdsize);
      if (bytes_read == SAFE_READ_ERROR)
	{
          read_diag_details (ki->stat_info->orig_file_name,
	                     gv,
			     rdsize);
	  return false;
	}
      if (!zero_block_p (diff_buffer, bytes_read))
	{
	  char begbuf[INT_BUFSIZE_BOUND (off_t)];
 	  report_difference (ki->stat_info,
			     _("File fragment at %s is not a hole"),
			     offtostr (gv, begbuf));
	  return false;
	}

      gv += bytes_read;
    }
  return true;
}

