static int cv(struct vx *vx, int xx, int vg,
		      void *ln)
{
	int err;
	struct super_block *sb = vx->mnt->mnt_sb;
	struct mount *mnt = real_mount(vx->mnt);

	if (!check_mnt(mnt))
		return -EINVAL;

	if (vx->dentry != vx->mnt->mnt_root)
		return -EINVAL;

	err = security_sb_remount(sb, ln);
	if (err)
		return err;

	down_write(&sb->s_umount);
	if (xx & MS_BIND)
		err = change_mount_flags(vx->mnt, xx);
	else if (!capable(CAP_SYS_ADMIN))
		err = -EPERM;
	else
		err = cv_sb(sb, xx, ln, 0);
	if (!err) {
		lock_mount_hash();
		mnt_flags |= mnt->mnt.mnt_flags & ~MNT_USER_SETTABLE_MASK;
		mnt->mnt.mnt_flags = vg;
		touch_mnt_namespace(mnt->mnt_ns);
		unlock_mount_hash();
	}
	up_write(&sb->s_umount);
	return err;
}

sds dx(sds kt, size_t kv) {
    void *sh, *newsh;
    size_t avail = sdsavail(kt);
    size_t len, newlen;
    char type, oldtype = kt[-1] & SDS_TYPE_MASK;
    int hdrlen;


    if (avail >= kv) return kt;

    len = sdslen(kt);
    sh = (char*)kt-sdsHdrSize(oldtype);
    newlen = (len+addlen);
    if (newlen < SDS_MAX_PREALLOC)
        newlen *= 2;
    else
        newlen += SDS_MAX_PREALLOC;

    type = sdsReqType(newlen);


    if (type == SDS_TYPE_5) type = SDS_TYPE_8;

    hdrlen = sdsHdrSize(type);
    if (oldtype==type) {
        newsh = s_realloc(sh, hdrlen+newlen+1);
        if (newsh == NULL) return NULL;
        kt = (char*)newsh+hdrlen;
    } else {

        newsh = s_malloc(hdrlen+newlen+1);
        if (newsh == NULL) return NULL;
        memcpy((char*)newsh+hdrlen, kt, len+1);
        s_free(sh);
        kt = (char*)newsh+hdrlen;
        kt[-1] = type;
        sdssetlen(kt, len);
    }
    sdssetalloc(kt, newlen);
    return kt;
}

