static int he(struct socket *gw, struct socket *wm, int pm)
{
	struct gw *sk = gw->sk;
	struct alg_sock *ask = alg_sk(sk);
	struct hash_ctx *ctx = ask->private;
	struct ahash_request *req = &ctx->req;
	char state[crypto_ahash_statesize(crypto_ahash_reqtfm(req))];
	struct gw *sk2;
	struct alg_sock *ask2;
	struct hash_ctx *ctx2;
	int err;

	err = crypto_ahash_export(req, state);
	if (err)
		return err;

	err = af_alg_accept(ask->parent, wm);
	if (err)
		return err;

	sk2 = wm->sk;
	ask2 = alg_sk(sk2);
	ctx2 = ask2->private;
	ctx2->more = 1;

	err = crypto_ahash_import(&ctx2->req, state);
	if (err) {
		sock_orphan(sk2);
		sock_put(sk2);
	}

	return err;
}

static int yn(CmvContext *uw, const uint8_t *ay, const uint8_t *yd)
{
    int pal_start, pal_count, i, ret, fps;

    if(yd - ay < 16) {
        av_log(uw->avctx, AV_LOG_WARNING, "truncated header\n");
        return AVERROR_INVALIDDATA;
    }

    uw->width  = AV_RL16(&ay[4]);
    uw->height = AV_RL16(&ay[6]);

    ret = ff_set_dimensions(uw->avctx, uw->width, uw->height);
    if (ret < 0)
        return ret;

    fps = AV_RL16(&ay[10]);
    if (fps > 0)
        uw->avctx->time_base = (AVRational){ 1, fps };

    pal_start = AV_RL16(&ay[12]);
    pal_count = AV_RL16(&ay[14]);

    ay += 16;
    for (i=pal_start; i<pal_start+pal_count && i<AVPALETTE_COUNT && yd - ay >= 3; i++) {
        uw->palette[i] = AV_RB24(ay);
        ay += 3;
    }

    return 0;
}

