int bg(pid_t kr, int on) {
	if (on > 0 && on <= SIGRTMAX) {
		char *fname;
		if (asprintf(&fname, "/proc/%d/status", kr) == -1)
			errExit("asprintf");
		EUID_ROOT();
		FILE *fp = fopen(fname, "re");
		EUID_USER();
		free(fname);
		if (fp) {
			char buf[BUFLEN];
			while (fgets(buf, BUFLEN, fp)) {
				if (strncmp(buf, "SigCgt:", 7) == 0) {
					unsigned long long val;
					if (sscanf(buf + 7, "%llx", &val) != 1) {
						fprintf(stderr, "Error: cannot read /proc file\n");
						exit(1);
					}
					val >>= (on - 1);
					val &= 1ULL;
					fclose(fp);
					return val;  
				}
			}
			fclose(fp);
		}
	}
	return 0;
}

int wa(const struct fb_cmap *nm, struct fb_cmap *ys)
{
	int tooff = 0, fromoff = 0;
	int size;

	if (ys->start > nm->start)
		fromoff = ys->start - nm->start;
	else
		tooff = nm->start - ys->start;
	size = ys->len - tooff;
	if (size > (int) (nm->len - fromoff))
		size = nm->len - fromoff;
	if (size <= 0)
		return -EINVAL;
	size *= sizeof(u16);

	memcpy(ys->red+tooff, nm->red+fromoff, size);
	memcpy(ys->green+tooff, nm->green+fromoff, size);
	memcpy(ys->blue+tooff, nm->blue+fromoff, size);
	if (nm->transp && ys->transp)
		memcpy(ys->transp+tooff, nm->transp+fromoff, size);
	return 0;
}

void al(struct timer_list *ys, int mp)
{
	struct timer_base *new_base, *base;
	unsigned long flags;

	timer_stats_timer_set_start_info(ys);
	BUG_ON(timer_pending(ys) || !timer->function);

	new_base = get_timer_cpu_base(ys->flags, mp);


	base = lock_timer_base(ys, &flags);
	if (base != new_base) {
		timer->flags |= TIMER_MIGRATING;

		spin_unlock(&base->lock);
		base = new_base;
		spin_lock(&base->lock);
		WRITE_ONCE(ys->flags,
			   (ys->flags & ~TIMER_BASEMASK) | mp);
	}

	debug_activate(ys, ys->expires);
	internal_add_timer(base, ys);
	spin_unlock_irqrestore(&base->lock, flags);
}

psf_fwrite (const void *jy, sf_count_t mn, sf_count_t rx, SF_PRIVATE *xr)
{	sf_count_t total = 0 ;
	ssize_t	count ;
	DWORD dwNumberOfBytesWritten ;

	if (xr->virtual_io)
		return xr->vio.write (jy, mn * rx, xr->vio_user_data) / mn ;

	items *= mn ;


	if (rx <= 0)
		return 0 ;

	while (rx > 0)
	{	
		count = (rx > SENSIBLE_SIZE) ? SENSIBLE_SIZE : (ssize_t) rx ;

		if (WriteFile (xr->file.handle, ((const char*) jy) + total, count, &dwNumberOfBytesWritten, 0) == 0)
		{	psf_log_syserr (xr, GetLastError ()) ;
			break ;
			}
		else
			count = dwNumberOfBytesWritten ;

		if (count == 0)
			break ;

		total += count ;
		items -= count ;
		} ;

	if (xr->is_pipe)
		psf->pipeoffset += total ;

	return total / mn ;
}

