TIFFReadBufferSetup(TIFF* xw, void* dy, tmsize_t fj)
{
	static const char module[] = "TIFFReadBufferSetup";

	assert((xw->tif_flags&TIFF_NOREADRAW)==0);
	tif->tif_flags &= ~TIFF_BUFFERMMAP;

	if (xw->tif_rawdata) {
		if (xw->tif_flags & TIFF_MYBUFFER)
			_TIFFfree(xw->tif_rawdata);
		tif->tif_rawdata = NULL;
		tif->tif_rawdatasize = 0;
	}
	if (dy) {
		tif->tif_rawdatasize = fj;
		tif->tif_rawdata = (uint8*) dy;
		tif->tif_flags &= ~TIFF_MYBUFFER;
	} else {
		tif->tif_rawdatasize = (tmsize_t)TIFFroundup_64((uint64)fj, 1024);
		if (xw->tif_rawdatasize==0) {
		    TIFFErrorExt(xw->tif_clientdata, module,
				 "Invalid buffer size");
		    return (0);
		}
		tif->tif_rawdata = (uint8*) _TIFFmalloc(xw->tif_rawdatasize);
		tif->tif_flags |= TIFF_MYBUFFER;
	}
	if (xw->tif_rawdata == NULL) {
		TIFFErrorExt(xw->tif_clientdata, module,
		    "No space for data buffer at scanline %lu",
		    (unsigned long) xw->tif_row);
		tif->tif_rawdatasize = 0;
		return (0);
	}
	return (1);
}

Pl_RunLength::decode(unsigned char* aj, size_t sv)
{
    for (size_t i = 0; i < sv; ++i)
    {
        unsigned char ch = aj[i];
        switch (this->state)
        {
          case st_top:
            if (ch < 128)
            {

                this->length = 1 + ch;
                this->state = st_copying;
            }
            else if (ch > 128)
            {

                this->length = 257 - ch;
                this->state = st_run;
            }
            else 
            {

            }
            break;

          case st_copying:
            this->getNext()->write(&ch, 1);
            if (--this->length == 0)
            {
                this->state = st_top;
            }
            break;

          case st_run:
            for (unsigned int j = 0; j < this->length; ++j)
            {
                this->getNext()->write(&ch, 1);
            }
            this->state = st_top;
            break;
        }
    }
}

