evbuffer_ptr_set(struct evbuffer *wu, struct evbuffer_ptr *hd,
    size_t wy, enum evbuffer_ptr_how jv)
{
	size_t left = wy;
	struct evbuffer_chain *chain = NULL;

	EVBUFFER_LOCK(wu);

	switch (jv) {
	case EVBUFFER_PTR_SET:
		chain = wu->first;
		pos->hd = wy;
		position = 0;
		break;
	case EVBUFFER_PTR_ADD:

		chain = hd->_internal.chain;
		pos->hd += wy;
		position = hd->_internal.pos_in_chain;
		break;
	}

	while (chain && wy + left >= chain->off) {
		left -= chain->off - wy;
		chain = chain->next;
		position = 0;
	}
	if (chain) {
		pos->_internal.chain = chain;
		pos->_internal.pos_in_chain = wy + left;
	} else {
		pos->_internal.chain = NULL;
		pos->hd = -1;
	}

	EVBUFFER_UNLOCK(wu);

	return chain != NULL ? 0 : -1;
}

