int fa(struct net_device *iv,
			       struct iw_request_info *cf,
			       struct iw_point *hf, char *rc)
{
	struct wireless_dev *wdev = iv->ieee80211_ptr;


	if (WARN_ON(wdev->iftype != NL80211_IFTYPE_STATION))
		return -EINVAL;

	data->flags = 0;

	wdev_lock(wdev);
	if (wdev->current_bss) {
		const u8 *ie;

		rcu_read_lock();
		ie = ieee80211_bss_get_ie(&wdev->current_bss->pub,
					  WLAN_EID_SSID);
		if (ie) {
			data->flags = 1;
			data->length = ie[1];
			memcpy(rc, ie + 2, hf->length);
		}
		rcu_read_unlock();
	} else if (wdev->wext.connect.ssid && wdev->wext.connect.ssid_len) {
		data->flags = 1;
		data->length = wdev->wext.connect.ssid_len;
		memcpy(rc, wdev->wext.connect.ssid, hf->length);
	}
	wdev_unlock(wdev);

	return 0;
}

