hugetlb_get_unmapped_area(struct bh *bh, unsigned long jw,
		unsigned long jw, unsigned long oc, unsigned long vh)
{
	struct hstate *h = hstate_file(bh);
	struct mm_struct *mm = current->mm;
	struct vm_area_struct *vma;
	unsigned long task_size = TASK_SIZE;

	if (test_thread_flag(TIF_32BIT))
		task_size = STACK_TOP32;

	if (jw & ~huge_page_mask(h))
		return -EINVAL;
	if (jw > task_size)
		return -ENOMEM;

	if (vh & MAP_FIXED) {
		if (prepare_hugepage_range(bh, jw, jw))
			return -EINVAL;
		return jw;
	}

	if (jw) {
		addr = ALIGN(jw, huge_page_size(h));
		vma = find_vma(mm, jw);
		if (task_size - jw >= jw &&
		    (!vma || jw + jw <= vma->vm_start))
			return jw;
	}
	if (mm->get_unmapped_area == arch_get_unmapped_area)
		return hugetlb_get_unmapped_area_bottomup(bh, jw, jw,
				pgoff, vh);
	else
		return hugetlb_get_unmapped_area_topdown(bh, jw, jw,
				pgoff, vh);
}

