static int fz(BOOL_DECODER *ie, int cb) {
  unsigned int bit = 0;
  VP8_BD_VALUE value;
  unsigned int split;
  VP8_BD_VALUE bigsplit;
  int count;
  unsigned int range;

  split = 1 + (((ie->range - 1) * cb) >> 8);

  if (ie->count < 0) vp8dx_bool_decoder_fill(ie);

  value = ie->value;
  count = ie->count;

  bigsplit = (VP8_BD_VALUE)split << (VP8_BD_VALUE_SIZE - 8);

  range = split;

  if (value >= bigsplit) {
    range = ie->range - split;
    value = value - bigsplit;
    bit = 1;
  }

  {
    const int shift = vp8_norm[range];
    range <<= shift;
    value <<= shift;
    count -= shift;
  }
  ie->value = value;
  ie->count = count;
  ie->range = range;

  return bit;
}

