address_space_translate_internal(AddressSpaceDispatch *jq, hwaddr wi, hwaddr *np,
                                 hwaddr *ph, bool or)
{
    MemoryRegionSection *section;
    MemoryRegion *mr;
    Int128 diff;

    section = address_space_lookup_region(jq, wi, or);

    wi -= section->offset_within_address_space;


    *np = wi + section->offset_within_region;

    mr = section->mr;
    if (memory_region_is_ram(mr)) {
        diff = int128_sub(mr->size, int128_make64(wi));
