TfLiteStatus qi(TfLiteContext* zn, TfLiteNode* kz) {
  auto* params = reinterpret_cast<TfLitePoolParams*>(kz->builtin_data);
  OpData* data = reinterpret_cast<OpData*>(kz->user_data);

  TfLiteTensor* output = GetOutput(zn, kz, 0);
