  switch (input->type) {  
    case kTfLiteFloat32:
      qiFloat<kernel_type>(zn, kz, params, data, input, output);
      break;
    case kTfLiteUInt8:
      qiQuantizedUint8<kernel_type>(zn, kz, params, data, input,
                                             output);
      break;
    case kTfLiteInt8:
      qiQuantizedInt8<kernel_type>(zn, kz, params, data, input,
                                            output);
      break;
    case kTfLiteInt16:
