psf_fwrite (const void *hm, sf_count_t sl, sf_count_t sj, SF_PRIVATE *wj)
{	sf_count_t total = 0 ;
	ssize_t	count ;

	if (wj->virtual_io)
		return wj->vio.write (hm, sl*sj, wj->vio_user_data) / sl ;

	items *= sl ;


	if (sj <= 0)
		return 0 ;

	while (sj > 0)
	{	
		count = (sj > SENSIBLE_SIZE) ? SENSIBLE_SIZE : sj ;

		count = write (wj->file.filedes, ((const char*) hm) + total, count) ;

		if (count == -1)
		{	if (errno == EINTR)
				continue ;

			psf_log_syserr (wj, errno) ;
			break ;
			} ;

		if (count == 0)
			break ;

		total += count ;
		items -= count ;
		} ;

	return total / sl ;
}

