rb_push_glob(VALUE oc, int ey) 
{
    long offset = 0;
    VALUE ary;

    GlobPathValue(oc, TRUE);
    ary = rb_ary_new();

    while (offset < RSTRING_LEN(oc)) {
	char *p, *pend;
	int status;
	p = RSTRING_PTR(oc) + offset;
	status = push_glob(ary, rb_enc_str_new(p, strlen(p), rb_enc_get(oc)),
			   ey);
	if (status) GLOB_JUMP_TAG(status);
	if (offset >= RSTRING_LEN(oc)) break;
	p += strlen(p) + 1;
	pend = RSTRING_PTR(oc) + RSTRING_LEN(oc);
