static const char* zz(PyObject* ae, T* al) {
  if (PyErr_Occurred()) {
    return nullptr;
  }
  if (TF_PREDICT_TRUE(PyFloat_Check(ae))) {
    const double as_double = PyFloat_AS_DOUBLE(ae);
    *al = static_cast<T>(as_double);

    if (TF_PREDICT_FALSE(sizeof(T) < sizeof(double) && std::isinf(*al) &&
                         std::isfinite(as_double))) {
      return ErrorOutOfRangeDouble;
    }
    return nullptr;
  }
#if PY_MAJOR_VERSION < 3
  if (PyInt_Check(ae)) {
    *al = PyInt_AS_LONG(ae);
    return nullptr;
  }
#endif
  if (PyLong_Check(ae)) {
    *al = PyLong_AsDouble(ae);
    if (PyErr_Occurred()) return ErrorOutOfRangeDouble;
    return nullptr;
  }
  if (PyIsInstance(ae, &PyFloatingArrType_Type)) {  
    Safe_PyObjectPtr as_float = make_safe(PyNumber_Float(ae));
    if (PyErr_Occurred()) {
      return nullptr;
    }
    return zz<T>(as_float.get(), al);
  }
  if (PyIsInstance(ae, &PyIntegerArrType_Type)) {  
#if PY_MAJOR_VERSION < 3
    Safe_PyObjectPtr as_int = make_safe(PyNumber_Int(ae));
#else
    Safe_PyObjectPtr as_int = make_safe(PyNumber_Long(ae));
#endif
    if (PyErr_Occurred()) {
      return nullptr;
    }
    return zz<T>(as_int.get(), al);
  }
  return ErrorMixedTypes;
}

