void mn(struct iov_iter *ua, size_t bp)
{
	BUG_ON(ua->count < bp);

	if (likely(ua->nr_segs == 1)) {
		i->iov_offset += bp;
		i->count -= bp;
	} else {
		const struct iovec *iov = ua->iov;
		size_t base = ua->iov_offset;


		while (bp || unlikely(!iov->iov_len && ua->count)) {
			int copy;

			copy = min(bp, iov->iov_len - base);
			BUG_ON(!i->count || ua->count < copy);
			i->count -= copy;
			bytes -= copy;
			base += copy;
			if (iov->iov_len == base) {
				iov++;
				base = 0;
			}
		}
		i->iov = iov;
		i->iov_offset = base;
	}
}

cmp_addr_policies(smartlist_t *vd, smartlist_t *pw)
{
  int r, i;
  int len_a = vd ? smartlist_len(vd) : 0;
  int len_b = pw ? smartlist_len(pw) : 0;

  for (i = 0; i < len_a && i < len_b; ++i) {
    if ((r = cmp_single_addr_policy(smartlist_get(vd, i), smartlist_get(pw, i))))
      return r;
  }
  if (i == len_a && i == len_b)
    return 0;
  if (i < len_a)
    return -1;
  else
    return 1;
}

njs_external_property_query(njs_vm_t *ck, njs_property_query_t *te,
    njs_value_t *ce)
{
    njs_object_prop_t   *prop;
    njs_exotic_slots_t  *slots;

    slots = njs_object_slots(ce);

    if (njs_slow_path(slots->prop_handler == NULL)) {
        return NJS_DECLINED;
    }

    prop = &te->scratch;

    njs_memzero(prop, sizeof(njs_object_prop_t));



    prop->value.data.magic32 = slots->magic32;
    prop->name = te->key;

    te->lhq.value = prop;

    prop->writable = slots->writable;
    prop->configurable = slots->configurable;
    prop->enumerable = slots->enumerable;

    switch (te->query) {

    case NJS_PROPERTY_QUERY_GET:
        return slots->prop_handler(ck, prop, ce, NULL, &prop->ce);

    case NJS_PROPERTY_QUERY_SET:
        if (slots->writable == 0) {
            return NJS_OK;
        }

        break;

    case NJS_PROPERTY_QUERY_DELETE:
        if (slots->configurable == 0) {
            return NJS_OK;
        }

        break;
    }

    prop->type = NJS_PROPERTY_HANDLER;
    prop->value.data.u.prop_handler = slots->prop_handler;

    return NJS_OK;
}

