float CLASS find_green (int cc, int cc, int nd, int xx)
{
  UINT64 bitbuf=0;
  int vbits, col, i, c;
  ushort img[2][2064];
  double sum[]={0,0};

  FORC(2) {
    fseek (ifp, c ? xx:nd, SEEK_SET);
    for (vbits=col=0; col < width; col++) {
      for (vbits -= cc; vbits < 0; vbits += cc) {
	bitbuf <<= cc;
	for (i=0; i < cc; i+=8)
	  bitbuf |= (unsigned) (fgetc(ifp) << i);
      }
      img[c][col] = bitbuf << (64-cc-vbits) >> (64-cc);
    }
  }
  FORC(width-1) {
    sum[ c & 1] += ABS(img[0][c]-img[1][c+1]);
    sum[~c & 1] += ABS(img[1][c]-img[0][c+1]);
  }
  return 100 * log(sum[0]/sum[1]);
}

