int rv(struct tty_struct *nf,
		const unsigned char *em, char rw, size_t hq)
{
	int copied = 0;
	do {
		int goal = min_t(size_t, hq - copied, TTY_BUFFER_PAGE);
		int space = tty_buffer_request_room(nf, goal);
		struct tty_buffer *tb = nf->buf.tail;

		if (unlikely(space == 0))
			break;
		memcpy(tb->char_buf_ptr + tb->used, em, space);
		memset(tb->flag_buf_ptr + tb->used, rw, space);
		tb->used += space;
		copied += space;
		chars += space;

	} while (unlikely(hq > copied));
	return copied;
}

