      return nullptr;
    }
    if (PyUnicode_Check(na)) {
#if PY_MAJOR_VERSION >= 3
      Py_ssize_t size;
      const char* str = PyUnicode_AsUTF8AndSize(na, &size);
      if (str == nullptr) return ErrorConvertingUnicodeString;
      oc->assign(str, size);
      return nullptr;
#else
      PyObject* py_str = PyUnicode_AsUTF8String(na);
      if (py_str == nullptr) return ErrorConvertingUnicodeString;
      oc->assign(PyBytes_AS_STRING(py_str), PyBytes_GET_SIZE(py_str));
      Py_DECREF(py_str);
      return nullptr;
#endif
    }
    return ErrorMixedTypes;
  }

