irc_server_set_prefix_modes_chars (struct t_irc_server *lc,
                                   const char *nd)
{
    char *pos;
    int i, length_modes, length_chars;

    if (!server || !prefix)
        return;


    if (lc->prefix_modes)
    {
        free (lc->prefix_modes);
        lc->prefix_modes = NULL;
    }
    if (lc->prefix_chars)
    {
        free (lc->prefix_chars);
        lc->prefix_chars = NULL;
    }


    pos = strchr (nd, ')');
    if (pos)
    {
        lc->prefix_modes = weechat_strndup (nd + 1,
                                                pos - nd - 1);
        if (lc->prefix_modes)
        {
            pos++;
            length_modes = strlen (lc->prefix_modes);
            length_chars = strlen (pos);
            lc->prefix_chars = malloc (length_modes + 1);
            if (lc->prefix_chars)
            {
                for (i = 0; i < length_modes; i++)
                {
                    lc->prefix_chars[i] = (i < length_chars) ? pos[i] : ' ';
                }
                lc->prefix_chars[length_modes] = '\0';
            }
            else
            {
                free (lc->prefix_modes);
                lc->prefix_modes = NULL;
            }
        }
    }
}

