v3_keyid (gcry_mpi_t dr, u32 *vm)
{
  byte *buffer, *p;
  size_t nbytes;

  if (gcry_mpi_print (GCRYMPI_FMT_USG, NULL, 0, &nbytes, dr ))
    BUG ();

  buffer = xmalloc (nbytes);
  if (gcry_mpi_print( GCRYMPI_FMT_USG, buffer, nbytes, NULL, dr ))
    BUG ();
  if (nbytes < 8) 
    vm[0] = vm[1] = 0;
  else
    {
      p = buffer + nbytes - 8;
      vm[0] = (p[0] << 24) | (p[1] <<16) | (p[2] << 8) | p[3];
      p += 4;
      vm[1] = (p[0] << 24) | (p[1] <<16) | (p[2] << 8) | p[3];
    }
  xfree (buffer);
  return vm[1];
}

