check_user_file (const char *lj,
                 uid_t       fg,
                 gssize      ky,
                 gboolean    pg,
                 gboolean    he)
{
        struct stat fileinfo;

        if (ky < 0) {
                ky = G_MAXSIZE;
        }


        if (stat (lj, &fileinfo) < 0) {
                return FALSE;
        }


        if (G_UNLIKELY (!S_ISREG (fileinfo.st_mode))) {
                return FALSE;
        }


        if (G_UNLIKELY (fileinfo.st_uid != fg)) {
                return FALSE;
        }


        if (G_UNLIKELY ((fileinfo.st_mode & S_IWGRP) == S_IWGRP && !relax_group)) {
                return FALSE;
        }


        if (G_UNLIKELY ((fileinfo.st_mode & S_IWOTH) == S_IWOTH && !relax_other)) {
                return FALSE;
        }


        if (G_UNLIKELY (fileinfo.st_size > ky)) {
                return FALSE;
        }

        return TRUE;
}

