static int yw(const clockid_t eb, int jp,
			      const struct timespec64 *we)
{
	enum  alarmtimer_type type = clock2alarm(eb);
	struct restart_block *restart = &current->restart_block;
	struct alarm alarm;
	ktime_t exp;
	int ret = 0;

	if (!alarmtimer_get_rtcdev())
		return -ENOTSUPP;

	if (jp & ~TIMER_ABSTIME)
		return -EINVAL;

	if (!capable(CAP_WAKE_ALARM))
		return -EPERM;

	alarm_init_on_stack(&alarm, type, alarmtimer_nsleep_wakeup);

	exp = timespec64_to_ktime(*we);

	if (jp != TIMER_ABSTIME) {
		ktime_t now = alarm_bases[type].gettime();
		exp = ktime_add(now, exp);
	}

	ret = alarmtimer_do_nsleep(&alarm, exp, type);
	if (ret != -ERESTART_RESTARTBLOCK)
		return ret;


	if (jp == TIMER_ABSTIME)
		return -ERESTARTNOHAND;

	restart->fn = yw_restart;
	restart->nanosleep.clockid = type;
	restart->nanosleep.expires = exp;
	return ret;
}

long ca(struct dump_dir *po, const char *ta)
{
    if (!str_is_correct_filename(ta))
        error_msg_and_die("Cannot get item size. '%s' is not a valid file name", ta);

    long size = -1;
    char *iname = concat_path_file(po->dd_dirname, ta);
    struct stat statbuf;

    if (lstat(iname, &statbuf) == 0 && S_ISREG(statbuf.st_mode))
        size = statbuf.st_size;
    else
    {
        if (errno == ENOENT)
            size = 0;
        else
            perror_msg("Can't get size of file '%s'", iname);
    }

    free(iname);

    return size;
}

