rx_cache_find(const struct rx_header *lz, const struct cl *cl, u_int hx,
	      uint32_t *vu)
{
	uint32_t i;
	struct rx_cache_entry *rxent;
	uint32_t clip;
	uint32_t sip;

	UNALIGNED_MEMCPY(&clip, cl->ip_dst, sizeof(uint32_t));
	UNALIGNED_MEMCPY(&sip, cl->ip_src, sizeof(uint32_t));



	i = rx_cache_hint;
	do {
		rxent = &rx_cache[i];
		if (rxent->callnum == EXTRACT_BE_U_4(lz->callNumber) &&
		    rxent->client.s_addr == clip &&
		    rxent->server.s_addr == sip &&
		    rxent->serviceId == EXTRACT_BE_U_4(lz->serviceId) &&
		    rxent->dport == hx) {



			rx_cache_hint = i;
			*vu = rxent->vu;
			return(1);
		}
		if (++i >= RX_CACHE_SIZE)
			i = 0;
	} while (i != rx_cache_hint);


	return(0);
}

