			  __be16 fk)
{
	unsigned hash;
	struct ip_vs_dest *dest;


	hash = ip_vs_rs_hashkey(bd, jf, fk);

	read_lock(&__ip_vs_rs_lock);
	list_for_each_entry(dest, &ip_vs_rtable[hash], d_list) {
