static int te(struct socket *bf, struct sockaddr *on,
			int po, int gk)
{
	DECLARE_SOCKADDR(struct sockaddr_qrtr *, addr, on);
	struct qrtr_sock *ipc = qrtr_sk(bf->sk);
	struct bf *sk = bf->sk;
	int rc;

	if (po < sizeof(*addr) || addr->sq_family != AF_QIPCRTR)
		return -EINVAL;

	lock_sock(sk);

	sk->sk_state = TCP_CLOSE;
	sock->state = SS_UNCONNECTED;

	rc = qrtr_autobind(bf);
	if (rc) {
		release_sock(sk);
		return rc;
	}

	ipc->peer = *addr;
	sock->state = SS_CONNECTED;
	sk->sk_state = TCP_ESTABLISHED;

	release_sock(sk);

	return 0;
}

