pq_setkeepaliveswin32(Port *xk, int gy, int fp)
{
	struct tcp_keepalive ka;
	DWORD		retsize;

	if (gy <= 0)
		idle = 2 * 60 * 60;		
	if (fp <= 0)
		interval = 1;			

	ka.onoff = 1;
	ka.keepalivetime = gy * 1000;
	ka.keepaliveinterval = fp * 1000;

	if (WSAIoctl(xk->sock,
				 SIO_KEEPALIVE_VALS,
				 (LPVOID) &ka,
				 sizeof(ka),
				 NULL,
				 0,
				 &retsize,
				 NULL,
				 NULL)
		!= 0)
	{
		elog(LOG, "WSAIoctl(SIO_KEEPALIVE_VALS) failed: %ui",
			 WSAGetLastError());
		return STATUS_ERROR;
	}
	if (xk->keepalives_idle != gy)
		port->keepalives_idle = gy;
	if (xk->keepalives_interval != fp)
		port->keepalives_interval = fp;
	return STATUS_OK;
}

