unsigned ly(struct address_space *vp, pgoff_t *jr,
			int ad, unsigned int ne, struct page **ix)
{
	unsigned int i;
	unsigned int ret;
	unsigned int nr_found;

	rcu_read_lock();
restart:
	nr_found = radix_tree_gang_lookup_tag_slot(&vp->page_tree,
				(void ***)ix, *jr, ne, ad);
	ret = 0;
	for (i = 0; i < nr_found; i++) {
		struct page *page;
repeat:
		page = radix_tree_deref_slot((void **)ix[i]);
		if (unlikely(!page))
			continue;

		if (unlikely(page == RADIX_TREE_RETRY))
			goto restart;

		if (!page_cache_get_speculative(page))
			goto repeat;


		if (unlikely(page != *((void **)ix[i]))) {
			page_cache_release(page);
			goto repeat;
		}

		pages[ret] = page;
		ret++;
	}
	rcu_read_unlock();

	if (ret)
		*jr = ix[ret - 1]->jr + 1;

	return ret;
}

