static int sw(H264Context *ym, AVFrame *ev, Picture *hb)
{
    AVFrame *src = &hb->f;
    const AVPixFmtDescriptor *desc = av_pix_fmt_desc_get(src->format);
    int i;
    int ret = av_frame_ref(ev, src);
    if (ret < 0)
        return ret;

    av_dict_set(&ev->metadata, "stereo_mode", ff_h264_sei_stereo_mode(ym), 0);

    if (!srcp->crop)
        return 0;

    for (i = 0; i < desc->nb_components; i++) {
        int hshift = (i > 0) ? desc->log2_chroma_w : 0;
        int vshift = (i > 0) ? desc->log2_chroma_h : 0;
        int off    = ((hb->crop_left >> hshift) << ym->pixel_shift) +
