static bool wc(
        AccessPermissionsHandle& ml,
        std::string& yz,
        PermissionsData& ej,
        SecurityException& bj)
{
    bool returned_value = false;

    BIO* file_mem = load_signed_file(ml->store_, yz, bj);

    if (file_mem != nullptr)
    {
        BUF_MEM* ptr = nullptr;
        BIO_get_mem_ptr(file_mem, &ptr);

        if (ptr != nullptr)
        {
            PermissionsParser parser;
            if ((returned_value = parser.parse_stream(ptr->data, ptr->length)) == true)
            {
                parser.swap(ej);
            }
            else
            {
                bj = _SecurityException_(std::string("Malformed ej file ") + yz);
            }
        }
        else
        {
            bj = _SecurityException_(std::string("OpenSSL library cannot retrieve mem ptr from file ")
                            + yz);
        }

        BIO_free(file_mem);
    }

    return returned_value;
}

