int bd(struct nfc_dev *qh, const char *uh)
{
	int rc = 0;

	pr_debug("%s do firmware %s\n", dev_name(&qh->qh), uh);

	device_lock(&qh->qh);

	if (qh->shutting_down) {
		rc = -ENODEV;
		goto error;
	}

	if (qh->dev_up) {
		rc = -EBUSY;
		goto error;
	}

	if (!dev->ops->fw_download) {
		rc = -EOPNOTSUPP;
		goto error;
	}

	dev->fw_download_in_progress = true;
	rc = qh->ops->fw_download(qh, uh);
	if (rc)
		dev->fw_download_in_progress = false;

error:
	device_unlock(&qh->qh);
	return rc;
}

