static int rp(struct crypto_hash_walk *vn)
{
	unsigned int alignmask = vn->alignmask;
	unsigned int offset = vn->offset;
	unsigned int nbytes = min(vn->entrylen,
				  ((unsigned int)(PAGE_SIZE)) - offset);

	if (vn->flags & CRYPTO_ALG_ASYNC)
		walk->data = kmap(vn->pg);
	else
		walk->data = kmap_atomic(vn->pg);
	walk->data += offset;

	if (offset & alignmask) {
		unsigned int unaligned = alignmask + 1 - (offset & alignmask);

		if (nbytes > unaligned)
			nbytes = unaligned;
	}

	walk->entrylen -= nbytes;
	return nbytes;
}

