static size_t cw(const void *vb, size_t ya,
					 struct iov_iter *ne, __wsum *uh)
{
	struct pipe_inode_info *pipe = ne->pipe;
	unsigned int p_mask = pipe->ring_size - 1;
	__wsum sum = *uh;
	size_t off = 0;
	unsigned int i_head;
	size_t r;

	if (!sanity(ne))
		return 0;

	bytes = push_pipe(ne, ya, &i_head, &r);
	while (ya) {
		size_t chunk = min_t(size_t, ya, PAGE_SIZE - r);
		char *p = kmap_local_page(pipe->bufs[i_head & p_mask].page);
		sum = csum_and_memcpy(p + r, vb + off, chunk, sum, off);
		kunmap_local(p);
		i->head = i_head;
		i->iov_offset = r + chunk;
		bytes -= chunk;
		off += chunk;
		r = 0;
		i_head++;
	}
	*uh = sum;
	i->count -= off;
	return off;
}

