Pipeline::SourceContainer::iterator ec(
    Pipeline::SourceContainer::iterator ij, Pipeline::SourceContainer* ip) {
    invariant(*ij == this);

    if (std::next(ij) == ip->end()) {
        return ip->end();
    }



    auto nextUnwind = dynamic_cast<DocumentSourceUnwind*>((*std::next(ij)).get());
    if (nextUnwind && !_unwind && nextUnwind->getUnwindPath() == _as.fullPath()) {
        _unwind = std::move(nextUnwind);
        ip->erase(std::next(ij));
        return ij;
    }
