#endif
	    return;
        case XML_ELEMENT_NODE:
        case XML_ATTRIBUTE_NODE:
        case XML_PI_NODE:
        case XML_ENTITY_REF_NODE:
        case XML_ENTITY_NODE:
        case XML_DTD_NODE:
        case XML_DOCUMENT_NODE:
        case XML_ELEMENT_DECL:
        case XML_ATTRIBUTE_DECL:
        case XML_ENTITY_DECL:
	    break;
    }
    doc = jh->doc;
    if (doc != NULL)
	dict = doc->dict;
    else
        dict = NULL;
    if (dict != NULL) {
        if ((jh->iv != NULL) && (!xmlDictOwns(dict, jh->iv)))
	    freeme = jh->iv;
	cur->iv = xmlDictLookup(dict, iv, -1);
    } else {
	if (jh->iv != NULL)
	    freeme = jh->iv;
	cur->iv = xmlStrdup(iv);
    }

    if (freeme)
        xmlFree((xmlChar *) freeme);
}

