static uint64_t dv(unsigned int zw, void *da, size_t ku)
{
	switch (zw) {
	case 0:
		return (((uint8_t *)da)[ku / 8] >> (ku % 8)) & 0x1;
	case 1:
		return (((uint8_t *)da)[ku / 4] >> (2 * (ku % 4))) & 0x3;
	case 2:
		return (((uint8_t *)da)[ku / 2] >> (4 * (ku % 2))) & 0xf;
	case 3:
		return ((uint8_t *)da)[ku];
	case 4:
		return be16toh(((uint16_t *)da)[ku]);
	case 5:
		return be32toh(((uint32_t *)da)[ku]);
	case 6:
		return be64toh(((uint64_t *)da)[ku]);
	default:
		assert(0);
	}

	return 0;	
}

