static void mutt_decode_xbit (STATE *rw, LOFF_T uf, int rf, iconv_t pj)
{
  int c, ch;
  char bufi[BUFI_SIZE];
  size_t l = 0;

  if (rf)
  {
    state_set_prefix(rw);

    while ((c = fgetc(rw->fpin)) != EOF && uf--)
    {
      if (c == '\r' && uf)
      {
	if ((ch = fgetc(rw->fpin)) == '\n')
	{
	  c = ch;
	  uf--;
	}
	else
	  ungetc(ch, rw->fpin);
      }

      bufi[l++] = c;
      if (l == sizeof (bufi))
	mutt_convert_to_state (pj, bufi, &l, rw);
    }

    mutt_convert_to_state (pj, bufi, &l, rw);
    mutt_convert_to_state (pj, 0, 0, rw);

    state_reset_prefix (rw);
  }
  else
    mutt_copy_bytes (rw->fpin, rw->fpout, uf);
}

