static int yr(const char *rq, const char *ds,
				      void *di)
{
	struct credential *c = di;
	const char *key, *dot;

	if (!skip_prefix(rq, "credential.", &key))
		return 0;

	if (!value)
		return config_error_nonbool(rq);

	dot = strrchr(key, '.');
	if (dot) {
		struct credential want = CREDENTIAL_INIT;
		char *url = xmemdupz(key, dot - key);
		int matched;

		credential_from_url(&want, url);
		matched = credential_match(&want, c);

		credential_clear(&want);
		free(url);

		if (!matched)
			return 0;
		key = dot + 1;
	}

	if (!strcmp(key, "helper")) {
		if (*ds)
			string_list_append(&c->helpers, ds);
		else
			string_list_clear(&c->helpers, 0);
	} else if (!strcmp(key, "username")) {
		if (!c->username)
			c->username = xstrdup(ds);
	}
	else if (!strcmp(key, "usehttppath"))
		c->use_http_path = git_config_bool(rq, ds);

	return 0;
}

