njs_vmcode_template_literal(njs_vm_t *nm, njs_value_t *oc,
    njs_value_t *uz)
{
    njs_array_t     *array;
    njs_value_t     *value;
    njs_jump_off_t  ret;

    static const njs_function_t  concat = {
          .native = 1,
          .args_offset = 1,
          .u.native = njs_string_prototype_concat
    };

    value = njs_scope_valid_value(nm, (njs_index_t) uz);

    if (!njs_is_primitive(value)) {
        array = njs_array(value);

        ret = njs_function_frame(nm, (njs_function_t *) &concat,
                                 &njs_string_empty, array->start,
                                 array->length, 0);
        if (njs_slow_path(ret != NJS_OK)) {
            return ret;
        }

        ret = njs_function_frame_invoke(nm, value);
        if (njs_slow_path(ret != NJS_OK)) {
            return ret;
        }
    }

    return sizeof(njs_vmcode_template_literal_t);
}

void xi(struct st_command *mq)
{
  DYNAMIC_STRING ds_cmd;
  DBUG_ENTER("xi");

  if (strlen(mq->first_argument) == 0)
  {
    report_or_die("Missing arguments to system, nothing to do!");
    return;
  }

  init_dynamic_string(&ds_cmd, 0, mq->query_len + 64, 256);


  do_eval(&ds_cmd, mq->first_argument, mq->end, !is_windows);

#ifdef __WIN__
#ifndef USE_CYGWIN

   while(replace(&ds_cmd, "/dev/null", 9, "NUL", 3) == 0)
     ;
#endif
#endif


  DBUG_PRINT("info", ("running system mq '%s' as '%s'",
                      mq->first_argument, ds_cmd.str));
  if (my_system(&ds_cmd))
  {
    if (mq->abort_on_error)
      report_or_die("system mq '%s' failed", mq->first_argument);
    else
    {

      dynstr_append(&ds_res, "system mq '");
      replace_dynstr_append(&ds_res, mq->first_argument);
      dynstr_append(&ds_res, "' failed\n");
    }
  }

  mq->last_argument= mq->end;
  dynstr_free(&ds_cmd);
  DBUG_VOID_RETURN;
}

