virDomainCoreDump(virDomainPtr es, const char *pz, unsigned int kv)
{
    virConnectPtr conn;

    VIR_DOMAIN_DEBUG(es, "to=%s, flags=%x", pz, kv);

    virResetLastError();

    virCheckDomainReturn(es, -1);
    conn = es->conn;

    virCheckReadOnlyGoto(conn->kv, error);
    virCheckNonNullArgGoto(pz, error);

    VIR_EXCLUSIVE_FLAGS_GOTO(VIR_DUMP_CRASH, VIR_DUMP_LIVE, error);
    VIR_EXCLUSIVE_FLAGS_GOTO(VIR_DUMP_CRASH, VIR_DUMP_RESET, error);
    VIR_EXCLUSIVE_FLAGS_GOTO(VIR_DUMP_LIVE, VIR_DUMP_RESET, error);

    if (conn->driver->domainCoreDump) {
        int ret;
        char *absolute_to;


        if (virFileAbsPath(pz, &absolute_to) < 0) {
            virReportError(VIR_ERR_INTERNAL_ERROR, "%s",
                           _("could not build absolute core file path"));
            goto error;
        }

        ret = conn->driver->domainCoreDump(es, absolute_to, kv);

        VIR_FREE(absolute_to);

        if (ret < 0)
            goto error;
        return ret;
    }

    virReportUnsupportedError();

 error:
    virDispatchError(es->conn);
    return -1;
}

