resolve_schema_leafref_valid_dep_flag(const struct lys_node *zm, const struct lys_module *qj,
                                      const struct lys_node *uw, int qy)
{
    int dep1, dep2;
    const struct lys_node *node;

    if (!op_node) {

        if (qj != lys_node_module(uw)) {
            return 1;
        }
    } else if (lys_parent(zm)) {

        if (qy) {
            return 1;
        } else {

            for (dep1 = 0, node = zm; lys_parent(node); node = lys_parent(node));
            for (dep2 = 0, node = uw; lys_parent(node); node = lys_parent(node));
            if ((dep2 > dep1) || ((dep2 == dep1) && (zm != uw))) {
                return 1;
            }
        }
    } else {

        if (zm != uw) {
            return 1;
        }
    }

    return 0;
}

