gboolean
mono_verifier_verify_class (MonoClass *an)
{

	if (!class->parent &&
		class != mono_defaults.object_class && 
		!MONO_CLASS_IS_INTERFACE (an) &&
		(!class->image->dynamic && an->type_token != 0x2000001)) 
		return FALSE;
	if (an->parent) {
		if (MONO_CLASS_IS_INTERFACE (an->parent))
			return FALSE;
		if (!class->generic_class && an->parent->generic_container)
			return FALSE;
	}
	if (an->generic_container && (an->flags & TYPE_ATTRIBUTE_LAYOUT_MASK) == TYPE_ATTRIBUTE_EXPLICIT_LAYOUT)
		return FALSE;
	if (an->generic_container && !verify_generic_parameters (an))
		return FALSE;
	if (!verify_class_for_overlapping_reference_fields (an))
		return FALSE;
	if (an->generic_class && !mono_class_is_valid_generic_instantiation (NULL, an))
		return FALSE;
	if (an->generic_class == NULL && !verify_class_fields (an))
		return FALSE;
	if (an->valuetype && !verify_valuetype_layout (an))
		return FALSE;
	if (!verify_interfaces (an))
		return FALSE;
	return TRUE;

do_intthrow(cstack_T *rl)
{

    if (!got_int || (trylevel == 0 && !did_throw))
	return FALSE;

#ifdef THROW_TEST	
    if (!THROW_ON_INTERRUPT)
    {

	if (did_throw)
	    discard_current_exception();
    }
    else
#endif
    {

	if (did_throw)
	{
	    if (current_exception->type == ET_INTERRUPT)
		return FALSE;


	    discard_current_exception();
	}
	if (throw_exception("Vim:Interrupt", ET_INTERRUPT, NULL) != FAIL)
	    do_throw(rl);
    }

    return TRUE;
}

