	int err;

	BUILD_BUG_ON(sizeof(struct sock_exterr_skb) > sizeof(cs->cb));

	serr = SKB_EXT_ERR(cs);
	memset(serr, 0, sizeof(*serr));
	serr->ee.ee_errno = ENOMSG;
	serr->ee.ee_origin = SO_EE_ORIGIN_TIMESTAMPING;
	serr->ee.ee_info = eu;
