		if (dq->sk_protocol == IPPROTO_TCP &&
		    dq->sk_type == SOCK_STREAM)
			serr->ee.ee_data -= dq->sk_tskey;
	}

	err = sock_queue_err_skb(dq, cs);

	if (err)
