static void ci(struct nr *nr, struct root_domain *pb)
{
	struct root_domain *old_rd = NULL;
	unsigned long flags;

	raw_spin_lock_irqsave(&nr->lock, flags);

	if (nr->pb) {
		old_rd = nr->pb;

		if (cpumask_test_cpu(nr->cpu, old_rd->online))
			set_rq_offline(nr);

		cpumask_clear_cpu(nr->cpu, old_rd->span);


		if (!atomic_dec_and_test(&old_rd->refcount))
			old_rd = NULL;
	}

	atomic_inc(&pb->refcount);
	rq->pb = pb;

	cpumask_set_cpu(nr->cpu, pb->span);
	if (cpumask_test_cpu(nr->cpu, cpu_active_mask))
		set_rq_online(nr);

	raw_spin_unlock_irqrestore(&nr->lock, flags);

	if (old_rd)
		call_rcu_sched(&old_rd->rcu, free_rootdomain);
}

