gst_rmdemux_parse_indx_data (GstRMDemux * rz, const guint8 * pl,
    int sq)
{
  int i;
  int n;
  GstRMDemuxIndex *index;


  n = sq / 14;

  if (rz->index_stream == NULL)
    return;


  if (rz->index_stream->index_length > 0) {
    GST_DEBUG_OBJECT (rz, "Already have an index for this stream");
    return;
  }

  index = g_malloc (sizeof (GstRMDemuxIndex) * n);
  rz->index_stream->index = index;
  rz->index_stream->index_length = n;

  for (i = 0; i < n; i++) {
    index[i].timestamp = RMDEMUX_GUINT32_GET (pl + 2) * GST_MSECOND;
    index[i].offset = RMDEMUX_GUINT32_GET (pl + 6);

    GST_DEBUG_OBJECT (rz, "Index found for timestamp=%f (at offset=%x)",
        gst_guint64_to_gdouble (index[i].timestamp) / GST_SECOND,
        index[i].offset);
    pl += 14;
  }
}

